head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDDST00303";
scwin.discloureArr = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_frm = { action: "", method: 'post', target: '' };

try { scwin.discloureArr =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jlddst00303' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jlddst00303.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name slc_searchGubun_onchange
 * @description slc_searchGubun 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_searchGubun_onchange = async function(e){
    try {
        await scwin.fnSearchCorpName();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst00303.slc_searchGubun_onchange' }); }
};

/**
 * @method
 * @name img_110_onclick
 * @description 「검색」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_110_onclick = async function(e){
    try {
        await scwin.fnSearchCorpName()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst00303.img_110_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnSearchCorpName
 * @description fn Search Corp Name 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearchCorpName = async function () {
    const sbmOptions = {
        id: "tx_fnSearchCorpName",
        method: "post",
        action: "/disclosure/detailsExt.do",
        ref: "dma_fnSearchCorpNameReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fncSearch
 * @description fnc Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fncSearch = async function () {
    const sbmOptions = {
        id: "tx_fncSearch",
        method: "post",
        action: "/disclosure/detailsExt.do",
        ref: "dma_fncSearchReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Search
 * @description Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/disclosure/detailsExt.do",
        ref: "dma_SearchReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_download
 * @description download 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_download = async function () {
    const sbmOptions = {
        id: "tx_download",
        method: "post",
        action: "/disclosure/detailsExt.do",
        ref: "dma_downloadReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function () {
    scwin.setTime('6M', 'fromData', 'toData');
    const scode = "null";
    const sValue = "null";
    const sName = "null";
    if (scode !== "") {
        $c.util.getComponent('dma_fnSearchCorpNameReq').set('disclosureType', sName);
        const dName = document.getElementsByName("disclosureTypeArr" + scode);
        const len1 = dName.length;
        const svs = sValue.split("|");
        for (let i = 0; i < dName.length; i++) {
            for (let j = 0; j < svs.length; j++) {
                if (dName[i].value === svs[j]) {
                    dName[i].checked = true;
                    if (sName !== "" && sName === "6") {
                        (document.frm || { elements: [] }).reportNm.value = "신규상장";
                    }
                    await scwin.fncSearch();
                }
            }
        }
    }
    await scwin.fnSearchCorpName();
};

/**
 * @method
 * @name disclosure_type
 * @description disclosure type 처리
 * @param {*} code code
 * @returns {void}
 * @hidden N
 */
scwin.disclosure_type = function (code) {
    const layer = $c.util.getComponent("layer" + code);
    const img = $c.util.getComponent("dTypeImg" + code);
    if (img.getValue() === "on") {
        img.src = "/img/btn/btn_" + code + ".gif";
        img.setValue("off");
    } else {
        img.src = "/img/btn/btn_" + code + "_on.gif";
        img.setValue("on");
    }
    if (img.getValue() === "on") {
        layer.style.display = 'inline';
    } else {
        if (img.getValue() === "off") {
            layer.style.display = 'none';
        }
    }
};

/**
 * @method
 * @name disclosure_window_check
 * @description disclosure window check 처리
 * @param {*} code code
 * @param {*} val val
 * @returns {void}
 * @hidden N
 */
scwin.disclosure_window_check = function (code, val) {
    const dName = document.getElementsByName("disclosureTypeArr" + code);
    let bl = true;
    if (val === "unCheck") {
        bl = false;
    }
    scwin.checkedBox(dName, bl);
};

/**
 * @method
 * @name checkedBox
 * @description checked Box 처리
 * @param {*} dName dName
 * @param {*} yn yn
 * @returns {void}
 * @hidden N
 */
scwin.checkedBox = function (dName, yn) {
    if (dName.length == null) {
        dName.checked = yn;
    } else {
        for (let j = 0; j < dName.length; j++) {
            dName[j].checked = yn;
        }
    }
};

/**
 * @method
 * @name order
 * @description order 처리
 * @param {*} startVal startVal
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.order = async function (startVal) {
    if (startVal === "ok") {
        await scwin.fnSearchCorpName();
    }
};

/**
 * @method
 * @name keyEvent
 * @description key Event 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.keyEvent = async function (e) {
    // TODO Stage2(규칙19): fieldEl(DOM 요소 계약) → 컴포넌트 getValue/setValue 계약으로 전환 필요
    const obj = ($c.util.fieldEl('AKCKwd', 'searchCorpName'));
    if ($c.util.getKeyCode(typeof e !== 'undefined' && e ? e : (typeof event !== 'undefined' ? event : undefined)) === 13 || (typeof e !== 'undefined' && e === 13)) {
        if ($c.util.getKeyCode(event) === 13) {
            chkValidChar(obj);
            scwin.corpType(obj);
            await scwin.fnSearchCorpName();
        }
    }
};

/**
 * @method
 * @name corpType
 * @description corp Type 처리
 * @param {*} val val
 * @returns {void}
 * @hidden N
 */
scwin.corpType = function (val) {
    if ($c.num.isNumber(val.value) === true) {
        if (val.value.length < 6 || val.value.length > 7) {
            val.value = "";
            $c.util.getComponent('dma_fnSearchCorpNameReq').set('searchCodeType', "");
            return false;
        } else {
            $c.util.getComponent('dma_fnSearchCorpNameReq').set('searchCodeType', "number");
        }
    } else {
        $c.util.getComponent('dma_fnSearchCorpNameReq').set('searchCodeType', "char");
    }
};

/**
 * @method
 * @name disclosureAllSetting
 * @description disclosure All Setting 처리
 * @returns {void}
 * @hidden N
 */
scwin.disclosureAllSetting = function () {
    const len = scwin.discloureArr.length;
    for (let x = 0; x < len; x++) {
        scwin.disclosureSetting(scwin.discloureArr[x]);
    }
};

/**
 * @method
 * @name disclosureSetting
 * @description disclosure Setting 처리
 * @param {*} code code
 * @returns {void}
 * @hidden N
 */
scwin.disclosureSetting = function (code) {
    const get_name = document.getElementsByName("disclosureTypeArr" + code);
    const set_name = (document.frm || { elements: [] }).elements["disclosureType"+code];
    const length = get_name.length;
    let check_setting = "";
    if (length == null) {
        if (get_name.checked === true) {
            check_setting += get_name.value + "|";
        }
    } else {
        for (let j = 0; j < length; j++) {
            if (get_name[j].checked === true) {
                check_setting += get_name[j].value + "|";
            }
        }
    }
    set_name.value = check_setting;
};

/**
 * @method
 * @name fnSearchCorpName
 * @description fn Search Corp Name 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpName = async function () {
    $c.util.getComponent('dma_fnSearchCorpNameReq').set('allRepIsuSrtCd', "");
    $c.util.getComponent('dma_fnSearchCorpNameReq').set('repIsuSrtCd', "");
    if (($c.util.getComponent('AKCKwd').getValue() == null ? '' : String($c.util.getComponent('AKCKwd').getValue())) !== '') {
        $c.util.getComponent('dma_fnSearchCorpNameReq').set('method', "searchCorpNameExt");
        scwin.form_frm.target = "iframe_1";
        await scwin.tx_fnSearchCorpName();
    } else {
        await scwin.fncSearch();
    }
};

/**
 * @method
 * @name fnSearchCorpCode
 * @description fn Search Corp Code 처리
 * @param {String} repIsuSrtCd repIsuSrtCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpCode = async function (repIsuSrtCd) {
    if (repIsuSrtCd === "") {
        if ($c.util.getComponent('dma_fnSearchCorpNameReq').get('searchCodeType') === "char") {
            await $c.win.alert("조회한 종목명이 존재하지 않습니다.");
            $c.util.getComponent('dma_fnSearchCorpNameReq').set('repIsuSrtCd', "");
            return;
        } else {
            if ($c.util.getComponent('dma_fnSearchCorpNameReq').get('searchCodeType') === "number") {
                await $c.win.alert("조회한 종목코드가 존재하지 않습니다.");
                $c.util.getComponent('dma_fnSearchCorpNameReq').set('repIsuSrtCd', "");
                return;
            }
        }
    } else {
        $c.util.getComponent('dma_fnSearchCorpNameReq').set('repIsuSrtCd', repIsuSrtCd);
        await scwin.fncSearch();
    }
};

/**
 * @method
 * @name setReportNameInfo
 * @description set Report Name Info 처리
 * @param {String} formCd formCd
 * @param {String} formNm formNm
 * @returns {void}
 * @hidden N
 */
scwin.setReportNameInfo = function (formCd, formNm) {
    (document.frm || { elements: [] }).reportNm.value = formNm;
};

/**
 * @method
 * @name fncSearch
 * @description fnc Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fncSearch = async function () {
    scwin.disclosureAllSetting();
    if (!$c.date.isDate($c.util.getComponent('cal_fromData').getValue())) {
        await $c.win.alert("시작일자 형식이 틀립니다");
        return;
    }
    if (!$c.date.isDate($c.util.getComponent('cal_toData').getValue())) {
        await $c.win.alert("종료일자 형식이 틀립니다");
        return;
    }
    if (!($c.date.diffDate($c.util.getComponent('cal_fromData').getValue(), $c.util.getComponent('cal_toData').getValue()) < 0 ? (await $c.win.alert('조회 기간이 올바르지 않습니다. 시작일자가 종료일자보다 늦습니다.'), false) : true)) {
        return;
    }
    if ($c.util.getComponent('dma_fnSearchCorpNameReq').get('repIsuSrtCd') !== "") {
        $c.util.getComponent('dma_fnSearchCorpNameReq').set('allRepIsuSrtCd', "");
    }
    if (($c.util.getComponent('AKCKwd').getValue() == null ? '' : String($c.util.getComponent('AKCKwd').getValue())) === '') {
        $c.util.getComponent('dma_fnSearchCorpNameReq').set('searchCodeType', "");
    }
    $c.util.getComponent('dma_fnSearchCorpNameReq').set('forward', "details_discls_mktact_sub_ext");
    $c.util.getComponent('dma_fnSearchCorpNameReq').set('method', "searchDetailsDisclsMktactSubExt");
    $c.util.getComponent("dma_fnSearchCorpNameReq").set("currentPageSize", document.iframe.document.iFrm.currentPageSize.value);
    $c.util.getComponent("dma_fnSearchCorpNameReq").set("pageIndex", "1");
    scwin.form_frm.target = "iframe";
    openWaitDiv(440, 445);
    await scwin.tx_fncSearch();
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    scwin.disclosureAllSetting();
    if (!$c.date.isDate($c.util.getComponent('cal_fromData').getValue())) {
        await $c.win.alert("시작일자 형식이 틀립니다");
        return;
    }
    if (!$c.date.isDate($c.util.getComponent('cal_toData').getValue())) {
        await $c.win.alert("종료일자 형식이 틀립니다");
        return;
    }
    if (!($c.date.diffDate($c.util.getComponent('cal_fromData').getValue(), $c.util.getComponent('cal_toData').getValue()) < 0 ? (await $c.win.alert('조회 기간이 올바르지 않습니다. 시작일자가 종료일자보다 늦습니다.'), false) : true)) {
        return;
    }
    if ($c.util.getComponent('dma_fnSearchCorpNameReq').get('repIsuSrtCd') !== "") {
        $c.util.getComponent('dma_fnSearchCorpNameReq').set('allRepIsuSrtCd', "");
    }
    if (($c.util.getComponent('AKCKwd').getValue() == null ? '' : String($c.util.getComponent('AKCKwd').getValue())) === '') {
        $c.util.getComponent('dma_fnSearchCorpNameReq').set('searchCodeType', "");
    }
    $c.util.getComponent('dma_fnSearchCorpNameReq').set('forward', "details_discls_mktact_sub_ext");
    $c.util.getComponent('dma_fnSearchCorpNameReq').set('method', "searchDetailsDisclsMktactSubExt");
    $c.util.getComponent("dma_fnSearchCorpNameReq").set("currentPageSize", document.iframe.document.iFrm.currentPageSize.value);
    $c.util.getComponent("dma_fnSearchCorpNameReq").set("pageIndex", document.iframe.document.iFrm.pageIndex.value);
    (document.frm || { elements: [] }).target = "iframe";
    await scwin.tx_fn_Search();
};

/**
 * @method
 * @name validation
 * @description validation 처리
 * @returns {void}
 * @hidden N
 */
scwin.validation = function () {
    const f = (document.frm || { elements: [] });
    let returnValue = false;
    if (($c.util.getComponent('AKCKwd').getValue() == null ? '' : String($c.util.getComponent('AKCKwd').getValue())) !== '') {
        returnValue = true;
    }
    if ($c.util.getComponent('dma_fnSearchCorpNameReq').get('allRepIsuSrtCd') !== "") {
        returnValue = true;
    }
    if (f.submitOblgNm.value !== "") {
        returnValue = true;
    }
    if (f.reportNm.value !== "") {
        returnValue = true;
    }
    const len = scwin.discloureArr.length;
    for (let x = 0; x < len; x++) {
        const dt = $c.util.getComponent("disclosureType" + scwin.discloureArr[x]);
        if (dt.getValue() !== "") {
            returnValue = true;
        }
    }
    return returnValue;
};

/**
 * @method
 * @name crossCheck
 * @description cross Check 처리
 * @param {*} val val
 * @param {Object} obj 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.crossCheck = async function (val, obj) {
    if (val === "1") {
        if (obj.value !== "") {
            $c.util.getComponent('dma_fnSearchCorpNameReq').set('oldSearchCorpName', obj.value);
        }
    } else {
        if (val === "2") {
            if (obj.value !== "") {
                if (($c.util.getComponent('AKCKwd').getValue() == null ? '' : String($c.util.getComponent('AKCKwd').getValue())) !== '') {
                    await $c.win.alert("해당항목 선택시 법인명이 초기화 됩니다.");
                }
                $c.util.getComponent("AKCKwd").setValue("");
            } else {
                $c.util.getComponent("AKCKwd").setValue($c.util.getComponent('dma_fnSearchCorpNameReq').get('oldSearchCorpName'));
            }
        }
    }
};

/**
 * @method
 * @name findCorpName
 * @description find Corp Name 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.findCorpName = async function () {
    const wUrl = "/common/corpList.do?method=loadInitPage&comnm_tffield=AKCKwd";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    await $c.win.openPopup((function (__u) { const __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(wUrl), { id: '법인명찾기', width: "600", height: "510" }, {});
};

/**
 * @method
 * @name setCorpInfo
 * @description set Corp Info 처리
 * @param {String} isurCd isurCd
 * @param {String} kisComCd kisComCd
 * @param {String} repIsuSrtCd repIsuSrtCd
 * @param {String} comNm comNm
 * @param {*} comAbbrv comAbbrv
 * @param {*} isurSymbl isurSymbl
 * @param {*} fssUnqNo fssUnqNo
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo = function (isurCd, kisComCd, repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo) {
    let str = "";
    str += "isurCd : " + isurCd + "\n";
    str += "kisComCd : " + kisComCd + "\n";
    str += "repIsuSrtCd : " + repIsuSrtCd + "\n";
    str += "comNm : " + comNm + "\n";
    str += "comAbbrv : " + comAbbrv + "\n";
    str += "isurSymbl : " + isurSymbl + "\n";
    str += "fssUnqNo : " + fssUnqNo + "\n";
    $c.util.getComponent("AKCKwd").setValue(repIsuSrtCd);
    $c.util.getComponent('dma_fnSearchCorpNameReq').set('oldSearchCorpName', comAbbrv);
    $c.util.getComponent('dma_fnSearchCorpNameReq').set('repIsuSrtCd', "A" + repIsuSrtCd);
};

/**
 * @method
 * @name setSubmitPersonInfo
 * @description set Submit Person Info 처리
 * @param {*} submitOblgAbbrv submitOblgAbbrv
 * @param {*} fssUnqNo fssUnqNo
 * @param {String} disclsSubmitprnTpCd disclsSubmitprnTpCd
 * @param {String} submitOblgNm submitOblgNm
 * @returns {void}
 * @hidden N
 */
scwin.setSubmitPersonInfo = function (submitOblgAbbrv, fssUnqNo, disclsSubmitprnTpCd, submitOblgNm) {
    (document.frm || { elements: [] }).submitOblgNm.value = submitOblgAbbrv;
};

/**
 * @method
 * @name download
 * @description download 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.download = async function () {
    if (($c.util.getComponent('AKCKwd').getValue() == null ? '' : String($c.util.getComponent('AKCKwd').getValue())) === '') {
        $c.util.getComponent('dma_fnSearchCorpNameReq').set('searchCodeType', "");
    }
    $c.util.getComponent("dma_fnSearchCorpNameReq").set("currentPageSize", document.iframe.document.iFrm.currentPageSize.value);
    $c.util.getComponent("dma_fnSearchCorpNameReq").set("pageIndex", document.iframe.document.iFrm.pageIndex.value);
    $c.util.getComponent('dma_fnSearchCorpNameReq').set('forward', "details_down");
    $c.util.getComponent('dma_fnSearchCorpNameReq').set('method', "searchDetailsSubExt");
    (document.frm || { elements: [] }).target = "iframe_2";
    await scwin.tx_download();
};

/**
 * @method
 * @name clickListComp
 * @description click List Comp 처리
 * @param {*} pCode pCode
 * @param {*} pName pName
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.clickListComp = async function (pCode, pName) {
    $c.util.getComponent("AKCKwd").setValue(pName);
    await scwin.fnSearchCorpName();
};

/**
 * @method
 * @name getCookieComCode
 * @description get Cookie Com Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getCookieComCode = async function () {
    const cookiesStr = scwin.GetCookie('krxComp');
    let totalArray;
    let newVal = "";
    if (cookiesStr != null) {
        totalArray = cookiesStr.split("/");
    }
    const j = 0;
    const sCookieVal = "";
    for (i = 0; j < 11 && i < totalArray.length - 1; i++) {
        const sCookieTemp = totalArray[i].split(",");
        if (i === 0) {
            newVal = newVal + "'" + sCookieTemp[1] + "'";
        } else {
            newVal = newVal + ",'" + sCookieTemp[1] + "'";
        }
    }
    $c.util.getComponent('dma_fnSearchCorpNameReq').set('repIsuSrtCd', "");
    $c.util.getComponent('dma_fnSearchCorpNameReq').set('allRepIsuSrtCd', newVal);
    await scwin.fncSearch();
};

/**
 * @method
 * @name GetCookie
 * @description Get Cookie 처리
 * @param {*} keyname keyname
 * @returns {void}
 * @hidden N
 */
scwin.GetCookie = function (keyname) { const v = $c.util.getSessionStorage(keyname); return (v === undefined || v === null) ? '' : v; };

/**
 * @method
 * @name setTime
 * @description set Time 처리
 * @returns {void}
 * @hidden N
 */
scwin.setTime = function () {
    const vCurDate = $c.date.formatDate("yyyy-mm-dd hh:mm:ss");
    txb_now.setValue("현재시각 : " + vCurDate);
    runClock();
};
